import icalendar
from datetime import datetime

def is_holiday(date: str) -> bool:
    try:
        dt = datetime.strptime(date, '%Y-%m-%d').date()
        with open('calendars/company_2025.ics', 'r') as f:
            cal = icalendar.Calendar.from_string(f.read())
            for component in cal.walk():
                if component.name == 'VEVENT':
                    start = component.get('DTSTART').dt.date()
                    if start == dt:
                        return True
        return False
    except:
        return False

import re

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float."""
    match = re.search(r'\$(\d{1,3}(?:,\d{3})*\.\d{2})', s)
    if not match:
        raise ValueError("Invalid price format")
    price_str = match.group(1).replace(',', '')
    return float(price_str)

